(async () => {
  const f = (path, method = 'GET', data) => wp.apiFetch({ path, method, data }).catch((e) => ({ error: e.code || e.message, status: e.data && e.data.status }));
  const gen = await f('/wc/v3/settings/general');
  const pick = (id) => (gen.find ? (gen.find((s) => s.id === id) || {}).value : gen);
  const taxes = await f('/wc/v3/taxes');
  const orders = await f('/wc/v3/orders?include=14,15&orderby=id&order=asc');
  const country = pick('woocommerce_default_country');
  const prov = await f('/wc-admin/settings/payments/providers', 'POST', { location: String(country).split(':')[0] });
  const onb = await f('/wc-admin/settings/payments/woopayments/onboarding', 'POST', {});
  return {
    store_country: country, currency: pick('woocommerce_currency'),
    taxes: Array.isArray(taxes) ? taxes.map((t) => [t.id, t.country, t.state, t.rate, t.name]) : taxes,
    orders: Array.isArray(orders) ? orders.map((o) => [o.id, o.status, o.currency, o.total, o.total_tax, o.billing.country, o.tax_lines.map((t) => t.rate_percent)]) : orders,
    providers: prov.providers ? prov.providers.map((p) => [p.id, p.state && p.state.supported, (p.title || '').slice(0, 40)]) : prov,
    woopayments: onb.state || onb,
  };
})()

