(async () => {
  const f = (path, method = 'GET', data) => wp.apiFetch({ path, method, data }).catch((e) => ({ error: e.code || e.message, status: e.data && e.data.status }));
  const out = {};
  for (const loc of ['US', 'GB', 'AE', 'SA', 'OM', 'YE', 'EG', 'JP']) {
    const set = await f('/wc-admin/settings/payments/country', 'POST', { location: loc });
    const onb = await f('/wc-admin/settings/payments/woopayments/onboarding', 'POST', {});
    const prov = await f('/wc-admin/settings/payments/providers', 'POST', { location: loc });
    const wp_ = (prov.providers || []).find((p) => p.id === 'woocommerce_payments') || {};
    out[loc] = { set: set.success, supported: onb.state ? onb.state.supported : onb, providers: (prov.providers || []).map((p) => p.id), woopayments_state: wp_.state, woopayments_onboarding: wp_.onboarding && { type: wp_.onboarding.type, state: wp_.onboarding.state } };
  }
  await f('/wc-admin/settings/payments/country', 'POST', { location: 'US' });
  return out;
})()
